SELECT 
    COUNT(*) AS totalCount,
    /* 열람: READ, ACCEPTED(수락), REJECTED(거절) 상태 포함 */
    COUNT(CASE WHEN so.scout_offer_status_cd IN ('READ', 'ACCEPTED', 'REJECTED') THEN 1 END) AS readCount,
    /* 미열람: PENDING(대기/미열람) 상태 */
    COUNT(CASE WHEN so.scout_offer_status_cd = 'PENDING' THEN 1 END) AS unreadCount
FROM tbl_scout_offer_m so
LEFT JOIN tbl_resume_m r ON so.resume_sq = r.resume_sq
WHERE r.user_sq = #{userSq}

SELECT so.scout_offer_sq AS scoutsSq, c.company_nm AS senderCompanyName, so.project_sq AS projectSq, p.project_ttl AS projectTitle, so.scout_offer_ttl AS title, so.scout_offer_cnt AS content, so.scout_offer_salary AS offeredPay, so.scout_offer_status_cd AS status, DATE_FORMAT(so.scout_offer_created_at_dtm, '%Y-%m-%d %H:%i:%s') AS createdAt, NULL AS expiredAt FROM tbl_scout_offer_m so LEFT JOIN tbl_company_s c ON so.company_sq = c.company_sq LEFT JOIN tbl_project_m p ON so.project_sq = p.project_sq LEFT JOIN tbl_resume_m r ON so.resume_sq = r.resume_sq WHERE r.user_sq = #{userSq}
AND so.scout_offer_status_cd IN ('READ', 'ACCEPTED', 'REJECTED')
AND so.scout_offer_status_cd = 'PENDING'
AND so.scout_offer_status_cd = #{status}
AND so.scout_offer_ttl LIKE CONCAT('%', #{keyword}, '%')
AND c.company_nm LIKE CONCAT('%', #{keyword}, '%')
AND (so.scout_offer_ttl LIKE CONCAT('%', #{keyword}, '%') OR c.company_nm LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY so.scout_offer_sq DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM tbl_scout_offer_m so
LEFT JOIN tbl_company_s c ON so.company_sq = c.company_sq
LEFT JOIN tbl_resume_m r ON so.resume_sq = r.resume_sq
WHERE r.user_sq = #{userSq}


    AND so.scout_offer_status_cd = #{status}





